// Class 10 English Communicative (Code 101) Preloaded Solutions Data Bundle (All 13 Units)
window.CHAPTERS_DATA = {"1":"<section class=\"chapter-section\" id=\"ch1\" data-book=\"Fiction\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">F.1</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">COMMUNICATIVE FICTION</div>\n      <h2>Chapter 1: Two Gentlemen of Verona</h2>\n      <p>A.J. Cronin — Devotion, Sacrifice & Nobility of Soul — CBSE Marking Scheme 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">I. Literature Reader Textbook Solutions & Analysis — CBSE Marking Scheme 2026-27</div>\n\n  <div class=\"q-card\" id=\"cf1_1\">\n    <div class=\"q-head\" onclick=\"toggleQ('cf1_1')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">What were the various jobs that Nicola and Jacopo did to earn money in Verona?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>The two brothers undertook an astonishing variety of arduous jobs in post-war Verona: they sold wild strawberries on the outskirts of the town, shined shoes in the public square, hawked newspapers late into the cold night at bus stops, conducted foreign tourists to historical sights like Juliet's tomb, and ran errands for merchants.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Breakdown 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Jobs: Selling wild strawberries, shining shoes, selling newspapers</span><span class=\"marking-marks\">1½ Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Guiding tourists to Juliet's tomb and running mercantile errands</span><span class=\"marking-marks\">1½ Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"fp1_2\">\n    <div class=\"q-head\" onclick=\"toggleQ('fp1_2')\">\n      <div class=\"q-num\">Q2</div>\n      <div class=\"q-text\">What tragic catastrophe had shattered the boys' family during the war?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>Their father, a well-known singer, was killed in the early stages of the war. A bomb destroyed their comfortable home, leaving Nicola, Jacopo, and their sister Lucia homeless and starving. The boys joined the resistance movement against the German occupation, living in the rubble. After the war ended, they returned to find Lucia suffering from tuberculosis of the spine.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Breakdown 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Father killed in war; family house destroyed by aerial bombing</span><span class=\"marking-marks\">1½ Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Sister Lucia afflicted with tuberculosis of the spine post-war</span><span class=\"marking-marks\">1½ Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"fp1_3\">\n    <div class=\"q-head\" onclick=\"toggleQ('fp1_3')\">\n      <div class=\"q-num\">Q3</div>\n      <div class=\"q-text\">Why were Nicola and Jacopo working so desperately without spending anything on food or clothes?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>Despite earning good money from multiple jobs, the boys dressed in ragged clothes and ate black bread and figs. Every single penny they earned was saved to pay for Lucia's expensive hospitalization, specialized nursing, and medical treatment at the hospital villa in Poleta, determined to cure her so she could sing again.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Breakdown 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Frugal lifestyle: Wore ragged clothes, ate only bread and figs</span><span class=\"marking-marks\">1½ Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Noble purpose: Financing sister Lucia's hospital treatment at Poleta</span><span class=\"marking-marks\">1½ Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"fp1_4\">\n    <div class=\"q-head\" onclick=\"toggleQ('fp1_4')\">\n      <div class=\"q-num\">Q4</div>\n      <div class=\"q-text\">Why did the narrator choose not to let the boys know that he had discovered their family secret?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>The narrator observed how fiercely proud, dignified, and self-reliant the boys were. They never sought pity or charity, keeping their sister's illness a closely guarded family secret. The narrator felt that telling them he knew would hurt their pride and compromise their delicate sense of dignity, so he honored their noble reserve in silence.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Breakdown 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Respected boys' fierce pride, independence, and refusal to take charity</span><span class=\"marking-marks\">1½ Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Preserved their dignity by not intruding on their sacred family secret</span><span class=\"marking-marks\">1½ Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"fp1_5\">\n    <div class=\"q-head\" onclick=\"toggleQ('fp1_5')\">\n      <div class=\"q-num\">Q5</div>\n      <div class=\"q-text\">'Two Gentlemen of Verona' redefines the concept of gentlemanliness. How do Nicola and Jacopo show that nobility is determined by sacrifice rather than wealth or lineage?</div>\n      <div class=\"q-marks\">8 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (Max Word Count)</div>\n        <div class=\"answer-text\">\n<p><strong>1. Subverting Conventional Gentlemanliness:</strong><br>A 'gentleman' is traditionally defined by high social standing, aristocratic pedigree, refined clothing, and leisure. In stark contrast, Nicola (thirteen) and Jacopo (twelve) were scruffy, ragged street urchins covered in shoe polish and grime. Yet, the author bestows upon them the title 'Gentlemen of Verona' because true gentlemanliness resides in moral character, integrity, and selflessness.</p><p><strong>2. Immense Sacrifice and Resilience:</strong><br>Bereft of parents, home, and childhood, the two boys refused to succumb to despair, crime, or begging. Instead, they took up backbreaking labor with stoic cheerfulness. They endured starvation and freezing night winds solely to keep their invalid sister alive.</p><p><strong>3. Moral Hope for Humanity:</strong><br>The narrator reflects that their quiet, uncomplaining devotion gave humanity a promise of hope for human society in a broken post-war world. Their self-sacrifice, pride, and unconditional sibling love represent the purest nobility known to mankind.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Breakdown 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Contrast between superficial aristocratic status and moral nobility</span><span class=\"marking-marks\">2½ Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Account of brothers' labor, stoicism, and complete selflessness for sister</span><span class=\"marking-marks\">3 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Thematic conclusion: Redefining post-war hope and human dignity</span><span class=\"marking-marks\">2½ Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\"><span>🎯 Competency-Based & Value-Based Questions — Unit 1</span><span class=\"cbq-badge\">CBSE 2026-27</span></div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\" style=\"border-left:4px solid #0284c7;\">\n        <div class=\"cbq-type\" style=\"color:#0284c7;\">Character & Ethical Analysis</div>\n        <div class=\"cbq-question\"><strong>Analysis:</strong> Compare and contrast the personalities of Nicola and Jacopo. How do they complement each other?</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\n        <div class=\"cbq-answer\"><p>Nicola, at thirteen, is serious, mature, cautious, and protective of family pride; he feels embarrassed when Jacopo asks the narrator for a car ride to Poleta. Jacopo, at twelve, is lively, impulsive, cheerful like a bird, and openly expressive. Nicola provides the responsible anchor and strategic leadership, while Jacopo infuses joyful energy into their harsh daily existence.</p></div>\n      </div>\n    </div>\n  </div>\n  <div class=\"chapter-nav-btns\">\n    <div></div>\n    <button class=\"ch-nav-btn\" onclick=\"window.scrollTo({top:0,behavior:'smooth'})\">↑ Back to Top</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(2)\">Next Unit →</button>\n  </div>\n</section>\n","2":"<section class=\"chapter-section\" id=\"ch2\" data-book=\"Fiction\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">F.2</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">COMMUNICATIVE FICTION</div>\n      <h2>Chapter 2: Mrs. Packletide's Tiger</h2>\n      <p>Saki (H.H. Munro) — Satire, Social Vanity & The Cost of Jealousy — CBSE Marking Scheme 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">I. Literature Reader Textbook Solutions & Analysis — CBSE Marking Scheme 2026-27</div>\n\n  <div class=\"q-card\" id=\"cf2_1\">\n    <div class=\"q-head\" onclick=\"toggleQ('cf2_1')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">What compelled Mrs. Packletide to shoot a tiger? What was her primary motive?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>Mrs. Packletide had no genuine passion for big-game hunting; her sole motive was poisonous jealousy towards her social rival, Loona Bimberton. Loona had recently been carried eleven miles in an airplane by an Algerian aviator and talked of nothing else. To outshine Loona, Mrs. Packletide resolved to shoot a tiger, procure a tiger-skin rug, wear a tiger-claw brooch, and splash her photograph across Parisian journals.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Breakdown 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Motive: Toxic jealousy of Loona Bimberton's 11-mile airplane ride</span><span class=\"marking-marks\">1½ Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Social goal: Boast tiger skin rug, tiger-claw brooch, dominate society press</span><span class=\"marking-marks\">1½ Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"cf2_2\">\n    <div class=\"q-head\" onclick=\"toggleQ('cf2_2')\">\n      <div class=\"q-num\">Q2</div>\n      <div class=\"q-text\">How did the villagers make the tiger hunt smooth and safe for Mrs. Packletide?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>Tempted by the massive bounty of one thousand rupees, the villagers posted boys around to herd a senile, toothless, infirm old tiger that had given up hunting wild game and lived on domestic cattle. Children were warned not to disturb the tiger's sleep, cheap goats were tethered to supply easy food, and a comfortable platform (machan) was constructed on a tree.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Breakdown 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Villagers lured with 1,000 rupees bounty; guarded a senile, infirm tiger</span><span class=\"marking-marks\">1½ Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Tethered bleating goat as bait and built comfortable tree platform</span><span class=\"marking-marks\">1½ Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"cf2_3\">\n    <div class=\"q-head\" onclick=\"toggleQ('cf2_3')\">\n      <div class=\"q-num\">Q3</div>\n      <div class=\"q-text\">How did the tiger actually die? What was the fatal error committed by Mrs. Packletide?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>When Mrs. Packletide fired her rifle, the bullet struck the tethered goat, killing it instantly. The old tiger was never touched by the bullet; it died of heart failure caused by the sudden, deafening report of the rifle at close quarters, collapsing dead from sheer cardiac shock.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Breakdown 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Bullet struck and killed the tethered goat, not the tiger</span><span class=\"marking-marks\">1½ Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Tiger died of heart failure/cardiac arrest caused by sudden rifle blast</span><span class=\"marking-marks\">1½ Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"cf2_4\">\n    <div class=\"q-head\" onclick=\"toggleQ('cf2_4')\">\n      <div class=\"q-num\">Q4</div>\n      <div class=\"q-text\">Who was Miss Louisa Mebbin? How did she exploit Mrs. Packletide's secret?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>Miss Louisa Mebbin was Mrs. Packletide's paid companion, possessed of an elder-sisterly attitude towards money. Having observed that the goat had the bullet hole and the tiger had none, she blackmailed Mrs. Packletide, threatening to expose the fraud unless Mrs. Packletide purchased her a lovely weekend cottage ('Les Fauves') at Dorking for six hundred and eighty pounds.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Breakdown 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Identity: Paid companion with a protective, stingy attitude towards money</span><span class=\"marking-marks\">1½ Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Blackmail: Extorted a weekend cottage at Dorking worth £680 to keep silent</span><span class=\"marking-marks\">1½ Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"cf2_5\">\n    <div class=\"q-head\" onclick=\"toggleQ('cf2_5')\">\n      <div class=\"q-num\">Q5</div>\n      <div class=\"q-text\">How does Saki satirize the hollow rivalry, artificiality, and pretentiousness of British high society in 'Mrs. Packletide's Tiger'?</div>\n      <div class=\"q-marks\">8 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (Max Word Count)</div>\n        <div class=\"answer-text\">\n<p><strong>1. Satire on Social Competition:</strong><br>Saki uses biting irony to mock the aristocracy's trivial rivalries. Mrs. Packletide risks thousands of rupees not for sport, but to humiliate Loona Bimberton. Loona, in turn, refuses to attend Mrs. Packletide's celebration dinner or look at the newspaper photographs on 'press of other engagements'.</p><p><strong>2. The Mockery of Colonial Big-Game Hunting:</strong><br>The heroic colonial safari is reduced to a commercial farce: an ancient, dying tiger pushed into place by bribed villagers, shot from an armchair platform with a missed bullet that hits a goat.</p><p><strong>3. Poetic Justice & The Final Irony:</strong><br>While Mrs. Packletide gains her public triumph over Loona, she is financially bled dry by the cunning Louisa Mebbin. When asked why she gave up hunting, Mrs. Packletide remarks wryly: <em>'The incidental expenses are so heavy.'</em> Saki proves that vanity always carries an exorbitant price tag.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Breakdown 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Critique of bourgeois rivalry between Mrs. Packletide and Loona Bimberton</span><span class=\"marking-marks\">2½ Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Farce of the staged tiger hunt, killing goat, tiger dying of heart attack</span><span class=\"marking-marks\">3 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Final financial irony: Louisa Mebbin's blackmail and famous closing line</span><span class=\"marking-marks\">2½ Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\"><span>🎯 Competency-Based & Value-Based Questions — Unit 2</span><span class=\"cbq-badge\">CBSE 2026-27</span></div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\" style=\"border-left:4px solid #0284c7;\">\n        <div class=\"cbq-type\" style=\"color:#0284c7;\">Irony & Humor</div>\n        <div class=\"cbq-question\"><strong>Analysis:</strong> How did Miss Mebbin name her weekend cottage, and what is the biting irony in that name?</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\n        <div class=\"cbq-answer\"><p>Miss Mebbin named her cottage 'The Cedars' or 'Les Fauves' (meaning 'The Wild Beasts'). The supreme irony is that this idyllic country home was acquired through the 'wild beast' hunt—yet neither the tiger was wild, nor was the companion gentle, proving that the truly predatory beasts were the humans participating in the fraud.</p></div>\n      </div>\n    </div>\n  </div>\n  <div class=\"chapter-nav-btns\">\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(1)\">← Previous Unit</button>\n    <button class=\"ch-nav-btn\" onclick=\"window.scrollTo({top:0,behavior:'smooth'})\">↑ Back to Top</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(3)\">Next Unit →</button>\n  </div>\n</section>\n","3":"<section class=\"chapter-section\" id=\"ch3\" data-book=\"Fiction\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">F.3</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">COMMUNICATIVE FICTION</div>\n      <h2>Chapter 3: The Letter</h2>\n      <p>Dhumaketu — Filial Longing, Separation & Bureaucratic Coldness — CBSE Marking Scheme 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">I. Literature Reader Textbook Solutions & Analysis — CBSE Marking Scheme 2026-27</div>\n\n  <div class=\"q-card\" id=\"cf3_1\">\n    <div class=\"q-head\" onclick=\"toggleQ('cf3_1')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">Who was Coachman Ali? How had his earlier life contrasted with his present existence?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>In his youth, Coachman Ali was a renowned, ruthless shikari (hunter) who could spot a partridge hidden in yellow grass and derived sadistic pleasure from watching parent birds weep over slaughtered offspring. However, after his only daughter Miriam married a soldier and departed for Punjab, he experienced the agony of loneliness. Converted by grief, he renounced hunting, realizing that love and separation govern all living beings.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Breakdown 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Past: Cruel, expert hunter slaughtering partridges and hares for sport</span><span class=\"marking-marks\">1½ Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Present: Lonely, elderly father converted by daughter Miriam's separation</span><span class=\"marking-marks\">1½ Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"cf3_2\">\n    <div class=\"q-head\" onclick=\"toggleQ('cf3_2')\">\n      <div class=\"q-num\">Q2</div>\n      <div class=\"q-text\">Describe Ali's five-year daily pilgrimage to the post office.</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>Every single morning at 4 a.m., wrapped in a tattered coat against the piercing cold, Ali walked through the sleeping town to the post office, treating it like a sacred shrine of pilgrimage. He sat silently in the same corner on a wooden bench, waiting patiently for a letter from Miriam. Over five agonizing years, not a single letter arrived, yet his faith remained unshakeable.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Breakdown 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Walked daily at 4 a.m. in bitter winter cold to post office for 5 years</span><span class=\"marking-marks\">1½ Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Treated post office as a sacred shrine; waited patiently in silence</span><span class=\"marking-marks\">1½ Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"cf3_3\">\n    <div class=\"q-head\" onclick=\"toggleQ('cf3_3')\">\n      <div class=\"q-num\">Q3</div>\n      <div class=\"q-text\">How did the postmaster and clerks treat Ali before his death?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>The clerks and peons viewed Ali as a standing village joke and an annoying lunatic. They would mockingly call out his name when sorting mail just to watch him leap up in vain hope. When Ali once dared to ask the haughty postmaster about his letter, the postmaster barked at him coldly: <em>'Do you think we are waiting here to deliver your daughter's letter? Go away, you pest!'</em></p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Breakdown 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Viewed as a madman and butt of cruel office jokes; called out fake name</span><span class=\"marking-marks\">1½ Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Postmaster scolded him harshly, calling him an annoying pest</span><span class=\"marking-marks\">1½ Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"cf3_4\">\n    <div class=\"q-head\" onclick=\"toggleQ('cf3_4')\">\n      <div class=\"q-num\">Q4</div>\n      <div class=\"q-text\">What arrangement did Ali make with clerk Lakshmi Das on his last day on earth?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>Feeling that his end was near and gasping for breath, Ali cornered the clerk Lakshmi Das. With trembling hands, he gave Lakshmi Das five golden guineas from his purse. In exchange, Ali extracted a sacred promise that whenever Miriam's letter arrived, Lakshmi Das would carry it directly to Ali's grave and place it there.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Breakdown 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Gave five gold guineas from his purse to clerk Lakshmi Das</span><span class=\"marking-marks\">1½ Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Sole condition: Deliver Miriam's letter to Ali's grave when it arrives</span><span class=\"marking-marks\">1½ Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"cf3_5\">\n    <div class=\"q-head\" onclick=\"toggleQ('cf3_5')\">\n      <div class=\"q-num\">Q5</div>\n      <div class=\"q-text\">Trace the dramatic transformation of the postmaster from an unfeeling bureaucrat to an empathetic, grief-stricken father.</div>\n      <div class=\"q-marks\">8 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (Max Word Count)</div>\n        <div class=\"answer-text\">\n<p><strong>1. Initial Apathy:</strong><br>The postmaster was a textbook administrative automaton—cold, arrogant, and indifferent to human sentiment. He dismissed Ali's five-year devotion as lunacy, unable to perceive the suffering heart beating beneath Ali's ragged coat.</p><p><strong>2. The Turning Point of Personal Suffering:</strong><br>Poetic justice struck when the postmaster's own daughter fell critically ill in a distant town. Suddenly, the postmaster found himself in the exact same furnace of agonizing suspense. He spent the entire night pacing anxiously, waiting for a telegram, startled by every postal thud.</p><p><strong>3. The Epiphany of Empathy:</strong><br>When he picked up an envelope and saw the name 'Coachman Ali', his heart leaped with remorse. He realized that mail is not merely paper with stamps, but living human heartbeats connecting anxious souls. When he learned from Lakshmi Das that Ali had died three months prior, the postmaster was overwhelmed with guilt. Accompanied by Lakshmi Das, he visited Ali's grave to lay the letter, weeping in profound repentance.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Breakdown 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Initial bureaucratic arrogance and callous treatment of Ali</span><span class=\"marking-marks\">2½ Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Postmaster's daughter's illness awakening the agony of waiting</span><span class=\"marking-marks\">3 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Epiphany at Ali's grave: Realizing letters represent human heartbeats</span><span class=\"marking-marks\">2½ Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\"><span>🎯 Competency-Based & Value-Based Questions — Unit 3</span><span class=\"cbq-badge\">CBSE 2026-27</span></div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\" style=\"border-left:4px solid #0284c7;\">\n        <div class=\"cbq-type\" style=\"color:#0284c7;\">Philosophical & Empathy Analysis</div>\n        <div class=\"cbq-question\"><strong>Analysis:</strong> Dhumaketu writes: 'The postmaster had never thought that letters were warm, pulsating human hearts.' Explain this profound revelation.</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\n        <div class=\"cbq-answer\"><p>To bureaucrats, letters are sterile postal cargo sorted by pincodes and weight. It was only when personal grief struck the postmaster that he realized every envelope carries the tears, laughter, prayers, and anxieties of human relationships. Ali's tragic death taught him that without empathy, administrative efficiency is mere cold machinery.</p></div>\n      </div>\n    </div>\n  </div>\n  <div class=\"chapter-nav-btns\">\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(2)\">← Previous Unit</button>\n    <button class=\"ch-nav-btn\" onclick=\"window.scrollTo({top:0,behavior:'smooth'})\">↑ Back to Top</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(4)\">Next Unit →</button>\n  </div>\n</section>\n","4":"<section class=\"chapter-section\" id=\"ch4\" data-book=\"Fiction\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">F.4</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">COMMUNICATIVE FICTION</div>\n      <h2>Chapter 4: A Shady Plot</h2>\n      <p>Elsie Brown — Comedy, Supernatural Satire & Domestic Turmoil — CBSE Marking Scheme 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">I. Literature Reader Textbook Solutions & Analysis — CBSE Marking Scheme 2026-27</div>\n\n  <div class=\"q-card\" id=\"cf4_1\">\n    <div class=\"q-head\" onclick=\"toggleQ('cf4_1')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">Why did John Hallock consider himself fortunate when writing ghost stories? What was Jenkins' demand?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>John Hallock, a ledger clerk by day, had no specialized skill or creative imagination for supernatural fiction, yet whenever Jenkins, the editor of a sensational magazine, demanded a spooky ghost story, ideas mysteriously flooded into his mind from nowhere. John considered himself lucky because ghost stories paid well, and Jenkins always insisted on something chilling and full of horrors.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Breakdown 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Lack of personal plots; ideas mysteriously appeared when needed</span><span class=\"marking-marks\">1½ Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Jenkins' demand: Highly sensational, chilling ghost stories for magazine</span><span class=\"marking-marks\">1½ Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"cf4_2\">\n    <div class=\"q-head\" onclick=\"toggleQ('cf4_2')\">\n      <div class=\"q-num\">Q2</div>\n      <div class=\"q-text\">Who was Helen the ghost? Why did ghosts organize the 'Writers' Inspiration Bureau'?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>Helen was an eccentric female ghost who, in her mortal life, had been a terrible writer of bad magazine stories. In the afterlife, ghosts formed the <strong>Writers' Inspiration Bureau</strong> to help struggling human authors with plots. However, she announced that ghosts were going on strike because humans were pestering them day and night with modern Ouija boards, pulling them away from their ghostly haunts.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Breakdown 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Helen: Ghost who organized Writers' Inspiration Bureau for authors</span><span class=\"marking-marks\">1½ Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Ghost strike: Exhausted by humans incessantly summoning them via Ouija boards</span><span class=\"marking-marks\">1½ Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"cf4_3\">\n    <div class=\"q-head\" onclick=\"toggleQ('cf4_3')\">\n      <div class=\"q-num\">Q3</div>\n      <div class=\"q-text\">What bargain did Helen offer John Hallock?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>Helen promised to provide John with another ghost story plot on one strict condition: that John use his personal influence to get all his friends, acquaintances, and family members to immediately stop playing with Ouija boards, allowing ghosts to enjoy peaceful rest.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Breakdown 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Condition: Persuade friends and family to boycott Ouija boards</span><span class=\"marking-marks\">1½ Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Reward: Providing John with an original plot for his magazine ghost story</span><span class=\"marking-marks\">1½ Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"cf4_4\">\n    <div class=\"q-head\" onclick=\"toggleQ('cf4_4')\">\n      <div class=\"q-num\">Q4</div>\n      <div class=\"q-text\">How did Lavinia's Ouija board party precipitate a domestic crisis for John?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>John's shopping-obsessed wife Lavinia bought an Ouija board at a bargain sale and hosted a party with her friends. Partnered with Miss Laura Hinkle, the Ouija indicator spelled out <strong>T-R-A-I-T-O-R</strong> and named <strong>H-E-L-E-N</strong>, accusing John of flirting with another woman. Lavinia was outraged, convinced her husband was conducting a secret affair with a woman named Helen, and threatened divorce.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Breakdown 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Lavinia hosted party; Ouija board spelled 'TRAITOR' and 'HELEN'</span><span class=\"marking-marks\">1½ Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Lavinia suspected infidelity and threatened immediate divorce</span><span class=\"marking-marks\">1½ Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"cf4_5\">\n    <div class=\"q-head\" onclick=\"toggleQ('cf4_5')\">\n      <div class=\"q-num\">Q5</div>\n      <div class=\"q-text\">Describe the comic climax of 'A Shady Plot'. How is John Hallock's marriage saved, and how does he obtain his ghost plot?</div>\n      <div class=\"q-marks\">8 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (Max Word Count)</div>\n        <div class=\"answer-text\">\n<p><strong>1. Lavinia's Confrontation:</strong><br>The next morning, Lavinia enters John's study with packed suitcases to bid him goodbye. She notices John desperately trying to conceal a figure behind him in the room, confirming her worst suspicions of an unfaithful husband.</p><p><strong>2. Materialization of Helen:</strong><br>Stepping forward to confront the intruder, Lavinia is astonished to find Helen the ghost fully materializing into thin air. Instead of shrieking in jealousy, Lavinia realizes that 'Helen' is literally a disembodied ghost, not a human mistress. Overwhelmed by relief that her husband was not cheating on her, Lavinia faints into John's arms.</p><p><strong>3. Burning the Board & The Climax:</strong><br>Gladys the cook enters demanding to leave because of eerie spirits; Lavinia pacifies her by feeding the cursed Ouija board into the fireplace. Helen smiles in gratitude at the destruction of the board and dissolves into thin air, leaving John with the complete, brilliant plot for his new ghost story.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Breakdown 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Lavinia's confrontation with suitcases and suspicion of mistress</span><span class=\"marking-marks\">2½ Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Helen materializes: Relief that rival is a harmless ghost, saving marriage</span><span class=\"marking-marks\">3 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Ouija board burned; Helen departs leaving John with perfect story plot</span><span class=\"marking-marks\">2½ Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\"><span>🎯 Competency-Based & Value-Based Questions — Unit 4</span><span class=\"cbq-badge\">CBSE 2026-27</span></div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\" style=\"border-left:4px solid #0284c7;\">\n        <div class=\"cbq-type\" style=\"color:#0284c7;\">Irony & Humor</div>\n        <div class=\"cbq-question\"><strong>Analysis:</strong> How does Elsie Brown make fun of supernatural fads and bourgeois shopping habits through Lavinia?</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\n        <div class=\"cbq-answer\"><p>Lavinia represents the gullible consumer seduced by every passing bourgeois fad. She buys duck-shaped ash-trays and Ouija boards simply because they are 'ducky bargains'. Her obsession with calling spirits turns into an absurd parlor game, mocking how superficial middle-class fads create domestic chaos out of nothing.</p></div>\n      </div>\n    </div>\n  </div>\n  <div class=\"chapter-nav-btns\">\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(3)\">← Previous Unit</button>\n    <button class=\"ch-nav-btn\" onclick=\"window.scrollTo({top:0,behavior:'smooth'})\">↑ Back to Top</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(5)\">Next Unit →</button>\n  </div>\n</section>\n","5":"<section class=\"chapter-section\" id=\"ch5\" data-book=\"Fiction\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">F.5</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">COMMUNICATIVE FICTION</div>\n      <h2>Chapter 5: Patol Babu, Film Star</h2>\n      <p>Satyajit Ray — Artistic Integrity, Dedication & The Unsung Hero — CBSE Marking Scheme 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">I. Literature Reader Textbook Solutions & Analysis — CBSE Marking Scheme 2026-27</div>\n\n  <div class=\"q-card\" id=\"cf5_1\">\n    <div class=\"q-head\" onclick=\"toggleQ('cf5_1')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">Who offered Patol Babu a film role, and why was Patol Babu ecstatic?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>Nishikanto Ghosh, Patol Babu's neighbor, arranged a small film role through his brother-in-law Naresh Dutt, who worked in film production. Patol Babu was ecstatic because fifty-two-year-old Patol had been a passionate, celebrated stage actor in his youth in pre-war Calcutta, and receiving a film role rekindled his dormant creative dreams.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Breakdown 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Offer arranged by Nishikanto Ghosh through brother-in-law Naresh Dutt</span><span class=\"marking-marks\">1½ Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Ecstatic because it revived his youthful theatrical passion and dreams</span><span class=\"marking-marks\">1½ Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"cf5_2\">\n    <div class=\"q-head\" onclick=\"toggleQ('cf5_2')\">\n      <div class=\"q-num\">Q2</div>\n      <div class=\"q-text\">What was the scene Patol Babu was hired for? What dialogue was he given?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>The scene involved a pedestrian collision: as the lead hero Chanchal Kumar rushed out of an office car into the building, Patol Babu, playing a preoccupied pedestrian, was to collide with him, head-on. To Patol Babu's immense dismay, his dialogue was a solitary monosyllabic word: <strong>'Oh!'</strong></p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Breakdown 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Scene: Pedestrian colliding with hero Chanchal Kumar on sidewalk</span><span class=\"marking-marks\">1½ Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Dialogue: Single monosyllabic exclamation ('Oh!')</span><span class=\"marking-marks\">1½ Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"cf5_3\">\n    <div class=\"q-head\" onclick=\"toggleQ('cf5_3')\">\n      <div class=\"q-num\">Q3</div>\n      <div class=\"q-text\">What words of his theatrical mentor Gogon Pakrashi inspired Patol Babu when he felt insulted by the tiny dialogue?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>Remembering his revered guru Gogon Pakrashi, Patol Babu recalled his golden advice: <em>'Remember one thing, Patol: however small a part you're offered, never consider it beneath your dignity to accept. An actor must squeeze the last drop of life and essence out of each single word.'</em> This saintly advice banished his hurt ego and fired his artistic devotion.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Breakdown 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Pakrashi's advice: Never consider any part beneath dignity</span><span class=\"marking-marks\">1½ Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Artistic duty: Squeeze the last drop of essence and life out of every word</span><span class=\"marking-marks\">1½ Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"cf5_4\">\n    <div class=\"q-head\" onclick=\"toggleQ('cf5_4')\">\n      <div class=\"q-num\">Q4</div>\n      <div class=\"q-text\">How did Patol Babu rehearse the monosyllable 'Oh!' to achieve perfection?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>Standing near a quiet pan shop, Patol Babu practiced saying 'Oh!' with multiple emotional inflections—pain, surprise, sorrow, panic, and irritated shock. He calculated step-lengths, facial contortions, and timing. He even suggested wearing a butterfly mustache and carrying an open newspaper to make the pedestrian collision look natural.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Breakdown 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Practiced multiple emotional inflections (sorrow, shock, pain, panic)</span><span class=\"marking-marks\">1½ Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Added artistic details: Step calculations, newspaper prop, butterfly mustache</span><span class=\"marking-marks\">1½ Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"cf5_5\">\n    <div class=\"q-head\" onclick=\"toggleQ('cf5_5')\">\n      <div class=\"q-num\">Q5</div>\n      <div class=\"q-text\">Why did Patol Babu leave the film set without collecting his payment? Discuss the triumph of artistic pride over commercial greed.</div>\n      <div class=\"q-marks\">8 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (Max Word Count)</div>\n        <div class=\"answer-text\">\n<p><strong>1. Flawless Execution of Shot:</strong><br>When the director yelled 'Action!', Patol Babu timed his collision with Chanchal Kumar to perfection, screaming 'Oh!' with a mix of anguish and surprise, landing gracefully. The director Baren Mullick praised him: <em>'Jolly good! A first-class shot!'</em></p><p><strong>2. Financial Need vs Creative Sanctity:</strong><br>Patol Babu desperately needed money; his wife struggled with household expenses every day. He knew Naresh Dutt would pay him twenty or twenty-five rupees for his day's work.</p><p><strong>3. The Sublimity of Artistic Dignity:</strong><br>Yet, standing in the shade, a wave of profound creative satisfaction washed over him. He realized that the pure joy of performing a role with absolute perfection was priceless. Receiving a petty twenty-rupee note would demean and commercialize the divine creative ecstasy he had just experienced. Choosing artistic dignity over pocket change, Patol Babu walked away toward the railway station, a true, triumphant artist.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Breakdown 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Director's praise for flawless execution of collision and dialogue</span><span class=\"marking-marks\">2½ Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Patol's dire financial need contrasted with supreme creative ecstasy</span><span class=\"marking-marks\">3 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Departure without payment: Choosing artistic dignity over commercialization</span><span class=\"marking-marks\">2½ Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\"><span>🎯 Competency-Based & Value-Based Questions — Unit 5</span><span class=\"cbq-badge\">CBSE 2026-27</span></div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\" style=\"border-left:4px solid #0284c7;\">\n        <div class=\"cbq-type\" style=\"color:#0284c7;\">Character & Ethical Analysis</div>\n        <div class=\"cbq-question\"><strong>Analysis:</strong> How does Satyajit Ray pay homage to millions of unsung background artists and daily-wage dreamers in cinema through Patol Babu?</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\n        <div class=\"cbq-answer\"><p>Cinema glitters with glamorous stars, but relies on thousands of nameless extras who perform tiny background roles. Patol Babu represents the silent soul of art—those who pour heart, rehearsals, and passion into half-second appearances without expecting fame or wealth. Satyajit Ray proves that greatness is not determined by the size of the billboard, but by the sincerity of one's dedication.</p></div>\n      </div>\n    </div>\n  </div>\n  <div class=\"chapter-nav-btns\">\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(4)\">← Previous Unit</button>\n    <button class=\"ch-nav-btn\" onclick=\"window.scrollTo({top:0,behavior:'smooth'})\">↑ Back to Top</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(6)\">Next Unit →</button>\n  </div>\n</section>\n","6":"<section class=\"chapter-section\" id=\"ch6\" data-book=\"Fiction\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">F.6</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">COMMUNICATIVE FICTION</div>\n      <h2>Chapter 6: Virtually True</h2>\n      <p>Paul Stewart — Sci-Fi Adventure, Virtual Reality & Digital Salvation — CBSE Marking Scheme 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">I. Literature Reader Textbook Solutions & Analysis — CBSE Marking Scheme 2026-27</div>\n\n  <div class=\"q-card\" id=\"cf6_1\">\n    <div class=\"q-head\" onclick=\"toggleQ('cf6_1')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">What startling newspaper headline caught Michael's attention? Why was the story miraculous?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>The newspaper headline screamed: <strong>'MIRACLE RECOVERY: BOY IN COMA WALKS OUT AFTER BRAIN SIMULATION'</strong>. It was miraculous because fourteen-year-old Sebastian Shultz had suffered catastrophic head injuries in a motorway accident and had been in a deep coma for weeks. Doctors had virtually given up hope when he suddenly awakened.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Breakdown 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Headline: 'Miracle Recovery: Boy in Coma Walks Out After Brain Simulation'</span><span class=\"marking-marks\">1½ Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Miracle: Sebastian awakened from hopeless coma following motor accident</span><span class=\"marking-marks\">1½ Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"cf6_2\">\n    <div class=\"q-head\" onclick=\"toggleQ('cf6_2')\">\n      <div class=\"q-num\">Q2</div>\n      <div class=\"q-text\">How had Sebastian Shultz's consciousness entered the interactive CD-ROM video games?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>At the exact instant of the car crash, Sebastian was playing an interactive virtual reality game on his laptop, plugged into a virtual reality helmet and glove. The violent collision caused a sudden surge of electrical energy that transferred and downloaded the memory and neural consciousness of his brain directly into the game's software and memory storage, trapping his persona inside cyberspace.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Breakdown 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Playing VR interactive game with helmet during motor crash</span><span class=\"marking-marks\">1½ Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Electrical surge transferred brain memory and consciousness into game software</span><span class=\"marking-marks\">1½ Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"cf6_3\">\n    <div class=\"q-head\" onclick=\"toggleQ('cf6_3')\">\n      <div class=\"q-num\">Q3</div>\n      <div class=\"q-text\">What were the three games where Michael attempted to rescue Sebastian before the final game?</div>\n      <div class=\"q-marks\">4 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>Michael entered three virtual scenarios attempting to save Sebastian:</p><ol><li><strong>Wild West:</strong> A dusty frontier town where Sebastian was the Sheriff; both were ambushed and Sebastian was gunned down.</li><li><strong>Dragonquest:</strong> A medieval fantasy castle where Michael rescued Princess Aurora, but the fire-breathing dragon devoured Sebastian.</li><li><strong>Jailbreak:</strong> A maximum-security prison cell escape where guard dogs attacked Sebastian on the roof.</li></ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Breakdown 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Wild West: Gunfight ambush at Alamo Saloon</span><span class=\"marking-marks\">1½ Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Dragonquest: Princess rescue where dragon captured Sebastian</span><span class=\"marking-marks\">1½ Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Jailbreak: Rooftop escape with guard dogs chasing</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"cf6_4\">\n    <div class=\"q-head\" onclick=\"toggleQ('cf6_4')\">\n      <div class=\"q-num\">Q4</div>\n      <div class=\"q-text\">How was Sebastian finally rescued in the game 'Warzone'?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>In 'Warzone', a war-torn city under sniper fire, Michael and Sebastian sprinted across the rubble towards a waiting evacuation helicopter. With seconds to spare, Michael leaped into the helicopter, reached out his hand, and dragged Sebastian aboard just as a bomb demolished the jeep behind them, achieving the target score and winning the game.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Breakdown 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Setting: Warzone with sniper fire and exploding buildings</span><span class=\"marking-marks\">1½ Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Rescue: Reached out from helicopter to pull Sebastian aboard before blast</span><span class=\"marking-marks\">1½ Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"cf6_5\">\n    <div class=\"q-head\" onclick=\"toggleQ('cf6_5')\">\n      <div class=\"q-num\">Q5</div>\n      <div class=\"q-text\">Analyze how Paul Stewart blends science fiction, virtual gaming, and human compassion in 'Virtually True'. What was the final email message?</div>\n      <div class=\"q-marks\">8 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (Max Word Count)</div>\n        <div class=\"answer-text\">\n<p><strong>1. Blurring Reality and Simulation:</strong><br>Stewart crafts a gripping narrative where interactive gaming hardware (visors, sensor gloves, CD-ROMs) becomes a bridge between life and death. The narrative explores how virtual reality can surpass human understanding by capturing digital consciousness.</p><p><strong>2. Compassion and Persistence:</strong><br>Michael is not merely playing to win high scores; he realizes a human soul is desperately crying for help ('PLEASE HELP TO RETRIEVE ME'). Michael's relentless commitment to restart game after game despite terrifying failures exemplifies extraordinary empathy.</p><p><strong>3. The Final Message:</strong><br>The next morning, Michael receives an email from the awakened Sebastian Shultz: <em>'Dear Michael, thank you. If it wasn't for you, I'd still be in that nightmare. Keep the games. You've earned them. Let's meet soon. Cheers, Sebastian.'</em> The message confirms that the digital rescue was real, proving that human connection transcends physical dimensions.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Breakdown 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Integration of virtual reality gaming technology with neuroscience</span><span class=\"marking-marks\">2½ Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Michael's empathy and perseverance in rescuing a trapped human consciousness</span><span class=\"marking-marks\">3 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Final email message confirming real-world recovery and true friendship</span><span class=\"marking-marks\">2½ Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\"><span>🎯 Competency-Based & Value-Based Questions — Unit 6</span><span class=\"cbq-badge\">CBSE 2026-27</span></div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\" style=\"border-left:4px solid #0284c7;\">\n        <div class=\"cbq-type\" style=\"color:#0284c7;\">Technology & Ethics</div>\n        <div class=\"cbq-question\"><strong>Analysis:</strong> How does 'Virtually True' reflect contemporary discussions on artificial intelligence, neural linking, and digital avatars?</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\n        <div class=\"cbq-answer\"><p>The story presaged modern advancements in neural-interface technology like brain-computer interfaces. It raises provocative philosophical questions: If human consciousness can be simulated or transferred into digital code, what defines life? Stewart warns of technological perils while highlighting that empathy and human solidarity remain the ultimate saving grace in any digital landscape.</p></div>\n      </div>\n    </div>\n  </div>\n  <div class=\"chapter-nav-btns\">\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(5)\">← Previous Unit</button>\n    <button class=\"ch-nav-btn\" onclick=\"window.scrollTo({top:0,behavior:'smooth'})\">↑ Back to Top</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(7)\">Next Unit →</button>\n  </div>\n</section>\n","7":"<section class=\"chapter-section\" id=\"ch7\" data-book=\"Poetry\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">P.1</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">COMMUNICATIVE POETRY</div>\n      <h2>Poem 1: The Frog and the Nightingale</h2>\n      <p>Vikram Seth — Exploitation, Flattery & Lack of Self-Confidence — CBSE Marking Scheme 2026-27</p>\n    </div>\n  </div>\n  <div class=\"poem-display-box\">\n    <div class=\"poem-body\">Once upon a time a frog\nCroaked away in Bingle Bog\nEvery night from dusk to dawn\nHe croaked awn and awn and awn.\n\nOther creatures loathed his voice,\nBut, alas, they had no choice,\nAnd the crass cacophony\nBlared out from the sumac tree...\n\nNeither stones nor prayers nor sticks,\nInsults or complained or bricks\nStilled the frog’s determination\nTo display his heart’s elation.</div>\n    <div class=\"poet-name\">— Vikram Seth</div>\n  </div>\n\n  <div class=\"ex-div\">I. Literature Reader Textbook Solutions & Analysis — CBSE Marking Scheme 2026-27</div>\n\n  <div class=\"q-card\" id=\"cp1_1\">\n    <div class=\"q-head\" onclick=\"toggleQ('cp1_1')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">How did the creatures of Bingle Bog react to the frog's song versus the nightingale's song?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>The creatures of Bingle Bog utterly loathed the frog's loud, harsh, crass cacophony, hurling stones, sticks, and bricks in vain to silence him. In contrast, when the nightingale sang her melodious song, the creatures were spellbound; ducks and herons waded in to listen, toads wept with emotion, and everyone applauded with cries of <em>'Bravo! Too divine! Encore!'</em></p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Breakdown 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Reaction to frog: Disgusted, hurled sticks/stones to stop his crude noise</span><span class=\"marking-marks\">1½ Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Reaction to nightingale: Spellbound, weeping with joy, shouting 'Encore!'</span><span class=\"marking-marks\">1½ Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"cp1_2\">\n    <div class=\"q-head\" onclick=\"toggleQ('cp1_2')\">\n      <div class=\"q-num\">Q2</div>\n      <div class=\"q-text\">How did the cunning frog deceive the naive nightingale into accepting him as her music trainer?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>The jealous frog introduced himself with boastful arrogance, claiming to be the owner of the sumac tree, a seasoned music maestro, and a famous critic for the 'Bog Trumpet'. While acknowledging her voice was sweet, he pointed out that it lacked 'force' and proper technique, offering to train her for an exorbitant fee. The gullible nightingale was flattered by praise from a 'maestro' and foolishly surrendered to his control.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Breakdown 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Boasted of owning sumac tree, being music critic for 'Bog Trumpet'</span><span class=\"marking-marks\">1½ Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Criticized her technique, offered training for a fee; nightingale flattered</span><span class=\"marking-marks\">1½ Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"cp1_3\">\n    <div class=\"q-head\" onclick=\"toggleQ('cp1_3')\">\n      <div class=\"q-num\">Q3</div>\n      <div class=\"q-text\">How did the frog commercially exploit and systematically destroy the nightingale?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>The frog turned her concerts into commercial ventures, charging entry fees and accumulating vast wealth while giving her nothing. He subjected her to cruel, exhausting training in bitter rain, made her sing for six hours without rest, insulted her constantly, and forced her to puff her lungs louder and sharper. Starved, exhausted, and terrified, the nightingale puffed up a desperate note until a vein in her head burst, and she died.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Breakdown 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Charged admission fees, hoarded wealth without paying the bird</span><span class=\"marking-marks\">1½ Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Forced extreme training in rain, caused exhaustion until vein burst and she died</span><span class=\"marking-marks\">1½ Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"cp1_4\">\n    <div class=\"q-head\" onclick=\"toggleQ('cp1_4')\">\n      <div class=\"q-num\">Q4</div>\n      <div class=\"q-text\">'The Frog and the Nightingale' is an allegorical fable on how lack of self-confidence and uncritical subservience lead to destruction. Analyze the themes and character traits.</div>\n      <div class=\"q-marks\">8 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (Max Word Count)</div>\n        <div class=\"answer-text\">\n<p><strong>1. The Predator (The Frog):</strong><br>The frog represents the untalented, loud, arrogant, and manipulative critic. Possessing no musical talent of his own, he maintains power through intimidation, commercial greed, and gaslighting. He cannot tolerate genuine genius and deliberately sabotages the nightingale to re-establish his monopoly over Bingle Bog.</p><p><strong>2. The Victim (The Nightingale):</strong><br>The nightingale represents gifted, sensitive artists who suffer from devastating self-doubt. Despite possessing a heavenly voice, she relies entirely on external validation. Her naive humility blinds her to the frog's jealousy. Even on her deathbed, she obeys his commands rather than trusting her own artistic instincts.</p><p><strong>3. Moral Lesson:</strong><br>At the end, the callous frog croaks: <em>'Your song must be your own.'</em> Seth delivers a powerful warning: an individual must possess self-belief and independence. Relying blindly on envious critics and bowing to authoritarian manipulators will inevitably choke one's natural talent to death.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Breakdown 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Analysis of frog as manipulative, untalented, greedy exploiter</span><span class=\"marking-marks\">2½ Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Analysis of nightingale's fatal flaw: Lack of self-worth and gullibility</span><span class=\"marking-marks\">3 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Moral allegory: Warning against toxic mentorship and loss of authentic voice</span><span class=\"marking-marks\">2½ Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\"><span>🎯 Competency-Based & Value-Based Questions — Unit 7</span><span class=\"cbq-badge\">CBSE 2026-27</span></div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\" style=\"border-left:4px solid #0284c7;\">\n        <div class=\"cbq-type\" style=\"color:#0284c7;\">Extract & Irony Analysis</div>\n        <div class=\"cbq-question\"><strong>Analysis:</strong> Read the frog's final words: 'Well, she had no brain, you see / Every bird must sing its own song.' Explain the cruel dramatic irony in his statement.</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\n        <div class=\"cbq-answer\"><p>The supreme irony is that the frog, who spent weeks brutally policing the nightingale's voice, altering her tempo, and forbidding her from singing naturally, hypocritically claims that 'every bird must sing its own song'. He murdered her through forced imitation and commercial exploitation, yet self-righteously blames her lack of intellect for her death.</p></div>\n      </div>\n    </div>\n  </div>\n  <div class=\"chapter-nav-btns\">\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(6)\">← Previous Unit</button>\n    <button class=\"ch-nav-btn\" onclick=\"window.scrollTo({top:0,behavior:'smooth'})\">↑ Back to Top</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(8)\">Next Unit →</button>\n  </div>\n</section>\n","8":"<section class=\"chapter-section\" id=\"ch8\" data-book=\"Poetry\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">P.2</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">COMMUNICATIVE POETRY</div>\n      <h2>Poem 2: Not Marble nor the Gilded Monuments (Sonnet 55)</h2>\n      <p>William Shakespeare — Immortality of Art, Poetry vs The Ravages of Time — CBSE Marking Scheme 2026-27</p>\n    </div>\n  </div>\n  <div class=\"poem-display-box\">\n    <div class=\"poem-body\">Not marble, nor the gilded monuments\nOf princes, shall outlive this powerful rhyme;\nBut you shall shine more bright in these contents\nThan unswept stone, besmear’d with sluttish time.\n\nWhen wasteful war shall statues overturn,\nAnd broils root out the work of masonry,\nNor Mars his sword nor war’s quick fire shall burn\nThe living record of your memory.\n\n‘Gainst death and all-oblivious enmity\nShall you pace forth; your praise shall still find room\nEven in the eyes of all posterity\nThat wear this world out to the ending doom.</div>\n    <div class=\"poet-name\">— William Shakespeare</div>\n  </div>\n\n  <div class=\"ex-div\">I. Literature Reader Textbook Solutions & Analysis — CBSE Marking Scheme 2026-27</div>\n\n  <div class=\"q-card\" id=\"cp2_1\">\n    <div class=\"q-head\" onclick=\"toggleQ('cp2_1')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">What will outlast marble statues and gilded monuments of princes according to Shakespeare?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>Shakespeare asserts that neither polished marble statues nor the gold-gilded monuments erected by royalty to perpetuate their glory will outlive his <strong>'powerful rhyme'</strong> (his poetry). While stone and gold decay, gather dust, and crumble under the ravages of time, his verse will shine with timeless, eternal brilliance.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Breakdown 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Poet's verse / powerful rhyme will outlast marble and gilded monuments</span><span class=\"marking-marks\">1½ Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Physical monuments decay and crumble; poetry remains timeless</span><span class=\"marking-marks\">1½ Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"cp2_2\">\n    <div class=\"q-head\" onclick=\"toggleQ('cp2_2')\">\n      <div class=\"q-num\">Q2</div>\n      <div class=\"q-text\">Why does the poet describe time as 'sluttish'? What happens to physical masonry during wars?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (Max Word Count)</div>\n        <div class=\"answer-text\">\n<p><strong>1. 'Sluttish Time':</strong> The poet personifies time as 'sluttish' (untidy, careless, dirty, and disrespectful) because time indiscriminately soils, weathers, tarnishes, and covers magnificent stone monuments with filth and dust, treating regal memorials with total disrespect.</p><p><strong>2. Devastation of War:</strong> Destructive wars overturn royal statues, and violent civil broils demolish masonry works, reducing majestic stone buildings to rubble.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Breakdown 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">'Sluttish time': Careless, disrespectful, besmearing statues with dirt/decay</span><span class=\"marking-marks\">1½ Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">War and fire demolish physical statues and masonry</span><span class=\"marking-marks\">1½ Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"cp2_3\">\n    <div class=\"q-head\" onclick=\"toggleQ('cp2_3')\">\n      <div class=\"q-num\">Q3</div>\n      <div class=\"q-text\">Why can neither Mars' sword nor war's fire burn the living record of the poet's friend?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>Mars is the Roman god of war. While sword and fire can annihilate solid physical structures made of stone and iron, they are completely powerless against poetry and memory. Because verse resides in the realm of human intellect, soul, and shared language, it is indestructible and immune to physical weapons.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Breakdown 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Mars (god of war) weapons can only destroy physical objects</span><span class=\"marking-marks\">1½ Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Poetic memory lives in human hearts and minds, transcending physical destruction</span><span class=\"marking-marks\">1½ Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"cp2_4\">\n    <div class=\"q-head\" onclick=\"toggleQ('cp2_4')\">\n      <div class=\"q-num\">Q4</div>\n      <div class=\"q-text\">How does Shakespeare immortalize his beloved friend in Sonnet 55? Discuss the theme of art triumphing over death and time.</div>\n      <div class=\"q-marks\">6 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (Max Word Count)</div>\n        <div class=\"answer-text\">\n<p><strong>1. Futility of Material Memorials:</strong><br>Monarchs and tyrants invest fortunes in erecting massive pyramids, marble tombs, and gilded effigies to keep their names alive. Shakespeare reveals that all physical monuments are doomed to oblivion by 'sluttish time' and devastating wars.</p><p><strong>2. Immortality of Poetic Verse:</strong><br>In contrast to perishable stone, the written word possesses immortal life. Shakespeare's sonnet acts as a living temple for his friend. Death and all-oblivious enmity cannot erase him; the friend will march forward through future generations ('all posterity') until the final Day of Judgment.</p><p><strong>3. The Ultimate Victory of Art:</strong><br>The concluding couplet summarizes this Renaissance humanist triumph: <em>'So, till the judgment that yourself arise, / You live in this, and dwell in lovers' eyes.'</em> Art conquers mortality by continuously resurrecting beauty in every reader's mind.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Breakdown 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Contrast between decaying stone monuments and immortal verse</span><span class=\"marking-marks\">2 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Power of poetry to overcome death, war, and historical oblivion</span><span class=\"marking-marks\">2 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Concluding couplet analysis: Living in lovers' eyes until Judgment Day</span><span class=\"marking-marks\">2 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\"><span>🎯 Competency-Based & Value-Based Questions — Unit 8</span><span class=\"cbq-badge\">CBSE 2026-27</span></div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\" style=\"border-left:4px solid #0284c7;\">\n        <div class=\"cbq-type\" style=\"color:#0284c7;\">Poetic Structure & Classical Allusion</div>\n        <div class=\"cbq-question\"><strong>Analysis:</strong> Explain the rhyme scheme and structure of Sonnet 55. What is the significance of referencing 'Mars' and 'ending doom'?</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\n        <div class=\"cbq-answer\"><p>Sonnet 55 follows the traditional Shakespearean sonnet form: 14 lines in iambic pentameter with the rhyme scheme **abab cdcd efef gg** (three quatrains and a rhyming couplet). Referencing **Mars** (Roman war god) highlights the ferocity of military conflict, while **'ending doom'** (biblical Day of Judgment) establishes that the friend's fame will outlive the entire span of human history itself.</p></div>\n      </div>\n    </div>\n  </div>\n  <div class=\"chapter-nav-btns\">\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(7)\">← Previous Unit</button>\n    <button class=\"ch-nav-btn\" onclick=\"window.scrollTo({top:0,behavior:'smooth'})\">↑ Back to Top</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(9)\">Next Unit →</button>\n  </div>\n</section>\n","9":"<section class=\"chapter-section\" id=\"ch9\" data-book=\"Poetry\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">P.3</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">COMMUNICATIVE POETRY</div>\n      <h2>Poem 3: Ozymandias</h2>\n      <p>Percy Bysshe Shelley — Tyranny, Transience of Power & The Mockery of Time — CBSE Marking Scheme 2026-27</p>\n    </div>\n  </div>\n  <div class=\"poem-display-box\">\n    <div class=\"poem-body\">I met a traveller from an antique land\nWho said: Two vast and trunkless legs of stone\nStand in the desert. Near them, on the sand,\nHalf sunk, a shattered visage lies, whose frown,\nAnd wrinkled lip, and sneer of cold command,\nTell that its sculptor well those passions read\nWhich yet survive, stamped on these lifeless things,\nThe hand that mocked them and the heart that fed;\nAnd on the pedestal these words appear:\n“My name is Ozymandias, King of Kings:\nLook on my Works, ye Mighty, and despair!”\nNothing beside remains. Round the decay\nOf that colossal Wreck, boundless and bare\nThe lone and level sands stretch far away.</div>\n    <div class=\"poet-name\">— Percy Bysshe Shelley</div>\n  </div>\n\n  <div class=\"ex-div\">I. Literature Reader Textbook Solutions & Analysis — CBSE Marking Scheme 2026-27</div>\n\n  <div class=\"q-card\" id=\"cp3_1\">\n    <div class=\"q-head\" onclick=\"toggleQ('cp3_1')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">What did the traveler from an antique land see in the desert?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>The traveler saw the ruins of a colossal ancient monument: two vast, torso-less legs of stone standing isolated in the desert. Near them, half-buried in the shifting sand, lay a shattered stone face (visage) whose sculpted frown, wrinkled lip, and sneer of cold command revealed the tyrannical arrogance of the king.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Breakdown 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Two vast and trunkless legs of stone standing in the desert</span><span class=\"marking-marks\">1½ Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Half-sunk shattered visage with frown and sneer of cold command</span><span class=\"marking-marks\">1½ Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"cp3_2\">\n    <div class=\"q-head\" onclick=\"toggleQ('cp3_2')\">\n      <div class=\"q-num\">Q2</div>\n      <div class=\"q-text\">How had the sculptor 'mocked' the passions of Ozymandias?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>The word 'mocked' has a double meaning: (i) to copy or imitate realistically, and (ii) to ridicule or expose with subtle irony. The skilled sculptor read the despotic nature of Ozymandias so accurately that he permanently carved the king's cruel arrogance and haughty sneer onto cold, lifeless granite, exposing his hubris to the ridicule of all future generations.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Breakdown 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Dual meaning: To replicate realistically + to satirize / deride</span><span class=\"marking-marks\">1½ Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Permanently captured tyrant's cruelty on stone, surviving his empire</span><span class=\"marking-marks\">1½ Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"cp3_3\">\n    <div class=\"q-head\" onclick=\"toggleQ('cp3_3')\">\n      <div class=\"q-num\">Q3</div>\n      <div class=\"q-text\">What was inscribed on the pedestal? What is the supreme irony of the inscription?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (Max Word Count)</div>\n        <div class=\"answer-text\">\n<p><strong>1. The Inscription:</strong> <em>'My name is Ozymandias, King of Kings: / Look on my Works, ye Mighty, and despair!'</em></p><p><strong>2. Supreme Irony:</strong> The arrogant pharaoh wanted rival rulers to look at his eternal empire and despair at their own insignificance. The devastating irony is that absolutely nothing remains of his works; his palaces and empire have dissolved into nothingness, surrounded only by empty, desolate, rolling sands.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Breakdown 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Pedestal inscription quoted accurately</span><span class=\"marking-marks\">1½ Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Situational irony: Despair intended for his power; now despairing at total ruin</span><span class=\"marking-marks\">1½ Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"cp3_4\">\n    <div class=\"q-head\" onclick=\"toggleQ('cp3_4')\">\n      <div class=\"q-num\">Q4</div>\n      <div class=\"q-text\">How does Shelley expose the vanity of political hubris and the triumph of nature and art in 'Ozymandias'?</div>\n      <div class=\"q-marks\">6 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (Max Word Count)</div>\n        <div class=\"answer-text\">\n<p><strong>1. Vanity of Tyranny:</strong><br>Ozymandias (Ramses II) believed his royal authority and stone monuments would withstand eternity. Shelley demonstrates that all political empires, dictatorships, and military conquests are transient dust before the relentless march of time.</p><p><strong>2. Triumph of Art Over Tyranny:</strong><br>While the King of Kings and his mighty works have vanished, the humble sculptor's artistic creation survives. The sculptor's perception of human pride outlasts the ruler who commanded it, proving that art preserves historical truth long after crowns turn to dust.</p><p><strong>3. Nature's Supreme Majesty:</strong><br>The final imagery—<em>'boundless and bare, / The lone and level sands stretch far away'</em>—is devastating. The vast, indifferent desert swallows the wreckage of human ego, proving that nature is the supreme sovereign of the cosmos.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Breakdown 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Vanity of political power: Dictators crumble into forgotten dust</span><span class=\"marking-marks\">2 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Art outlasting empire: Sculptor's hand and insight immortalized</span><span class=\"marking-marks\">2 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Nature's victory: Desert sands reigning supreme over human ruins</span><span class=\"marking-marks\">2 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\"><span>🎯 Competency-Based & Value-Based Questions — Unit 9</span><span class=\"cbq-badge\">CBSE 2026-27</span></div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\" style=\"border-left:4px solid #0284c7;\">\n        <div class=\"cbq-type\" style=\"color:#0284c7;\">Literary Devices & Alliteration</div>\n        <div class=\"cbq-question\"><strong>Analysis:</strong> Identify the alliterative phrases in the final lines: 'boundless and bare' and 'lone and level sands'. How do they reinforce the poem's atmosphere?</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\n        <div class=\"cbq-answer\"><p>The alliteration in **'boundless and bare'** and **'lone and level sands'** produces a flat, elongated, whispering rhythm. The repetitive 'b' and 'l' sounds emphasize boundless emptiness, vastness, and eternal stillness, sonically evoking the infinite, uninterrupted horizon of the desert where human pride has vanished without a trace.</p></div>\n      </div>\n    </div>\n  </div>\n  <div class=\"chapter-nav-btns\">\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(8)\">← Previous Unit</button>\n    <button class=\"ch-nav-btn\" onclick=\"window.scrollTo({top:0,behavior:'smooth'})\">↑ Back to Top</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(10)\">Next Unit →</button>\n  </div>\n</section>\n","10":"<section class=\"chapter-section\" id=\"ch10\" data-book=\"Poetry\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">P.4</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">COMMUNICATIVE POETRY</div>\n      <h2>Poem 4: The Rime of the Ancient Mariner</h2>\n      <p>Samuel Taylor Coleridge — Sin, Retribution & Reverence for Nature — CBSE Marking Scheme 2026-27</p>\n    </div>\n  </div>\n  <div class=\"poem-display-box\">\n    <div class=\"poem-body\">It is an ancient Mariner,\nAnd he stoppeth one of three.\n‘By thy long grey beard and glittering eye,\nNow wherefore stopp’st thou me?...\n\nThe ship was cheered, the harbour cleared,\nMerrily did we drop\nBelow the kirk, below the hill,\nBelow the lighthouse top...\n\nAnd now the STORM-BLAST came, and he\nWas tyrannous and strong:\nHe struck with his o’ertaking wings,\nAnd chased us south along...\n\nAnd through the drifts the snowy clifts\nDid send a dismal sheen:\nNor shapes of men nor beasts we ken—\nThe ice was all between.</div>\n    <div class=\"poet-name\">— Samuel Taylor Coleridge</div>\n  </div>\n\n  <div class=\"ex-div\">I. Literature Reader Textbook Solutions & Analysis — CBSE Marking Scheme 2026-27</div>\n\n  <div class=\"q-card\" id=\"cp4_1\">\n    <div class=\"q-head\" onclick=\"toggleQ('cp4_1')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">How does the Ancient Mariner detain the Wedding Guest? Why does the guest listen?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>The Ancient Mariner stops one of three guests on their way to a wedding. When the guest tries to brush him off, the mariner holds him with his <strong>'glittering eye'</strong>. The Wedding Guest is spellbound by the hypnotic, supernatural intensity of the mariner's gaze, standing still like a three-year-old child, powerless to walk away.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Breakdown 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Detained by hypnotic stare of the mariner's 'glittering eye'</span><span class=\"marking-marks\">1½ Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Guest spellbound like a child, listening helplessly to the tale</span><span class=\"marking-marks\">1½ Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"cp4_2\">\n    <div class=\"q-head\" onclick=\"toggleQ('cp4_2')\">\n      <div class=\"q-num\">Q2</div>\n      <div class=\"q-text\">How was the ship received by the South Pole ice, and how was the Albatross greeted by the crew?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>Driven by a ferocious storm blast, the ship was trapped in a terrifying Antarctic realm of mist and snow where ice mast-high cracked, growled, and roared like demonic sounds. Suddenly, an <strong>Albatross</strong> appeared through the fog. The delighted crew greeted it as a Christian soul sent by God, feeding it food it had never eaten, as it split the ice and brought a favorable south wind.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Breakdown 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Trapped in Antarctic ice roaring and cracking like monsters</span><span class=\"marking-marks\">1½ Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Albatross hailed as a holy omen; ice split and favorable wind blew</span><span class=\"marking-marks\">1½ Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"cp4_3\">\n    <div class=\"q-head\" onclick=\"toggleQ('cp4_3')\">\n      <div class=\"q-num\">Q3</div>\n      <div class=\"q-text\">What terrible crime did the Ancient Mariner commit? Why was it senseless and unprovoked?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>In a moment of wanton cruelty and perverse madness, the Ancient Mariner shot the innocent, friendly Albatross with his <strong>crossbow</strong>. It was completely senseless and unprovoked because the noble bird had brought companionship, split the frozen ice pack, summoned favorable navigational winds, and never harmed a soul.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Breakdown 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Crime: Shot the innocent Albatross with his crossbow</span><span class=\"marking-marks\">1½ Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Senseless: Bird had brought good wind, cracked ice, and befriended sailors</span><span class=\"marking-marks\">1½ Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"cp4_4\">\n    <div class=\"q-head\" onclick=\"toggleQ('cp4_4')\">\n      <div class=\"q-num\">Q4</div>\n      <div class=\"q-text\">Describe the curse that fell upon the ship in the silent equatorial sea.</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>The wind died suddenly and the sails collapsed. The ship was stuck motionless: <em>'Day after day, day after day, / We stuck, nor breath nor motion; / As idle as a painted ship / Upon a painted ocean.'</em> Under a burning copper sun, water supplies evaporated, wooden boards shrank, rotting slimy creatures crawled upon the slimy sea, and sailors' tongues choked with thirst: <em>'Water, water, everywhere, / Nor any drop to drink.'</em></p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Breakdown 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Motionless ship compared to 'painted ship upon a painted ocean'</span><span class=\"marking-marks\">1½ Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Extreme thirst ('nor any drop to drink') and rotting slimy sea</span><span class=\"marking-marks\">1½ Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"cp4_5\">\n    <div class=\"q-head\" onclick=\"toggleQ('cp4_5')\">\n      <div class=\"q-num\">Q5</div>\n      <div class=\"q-text\">Analyze the moral, environmental, and spiritual themes of 'The Rime of the Ancient Mariner'. Why did the sailors hang the dead bird around the mariner's neck?</div>\n      <div class=\"q-marks\">8 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (Max Word Count)</div>\n        <div class=\"answer-text\">\n<p><strong>1. Violation of the Sacred Covenant of Nature:</strong><br>Coleridge's epic poem is an ecological parable. The Albatross is not merely a seabird, but God's creation embodying universal life. Killing it without motive violates the sacred bond between humanity and the natural world, bringing immediate cosmic retribution.</p><p><strong>2. Burden of Guilt (The Hanging Albatross):</strong><br>When water runs out and death looms, the angry sailors blame the mariner for their impending doom. Instead of a cross around his neck, they hang the heavy, dead Albatross as an outward badge of sin, guilt, and environmental curse.</p><p><strong>3. Redemption Through Universal Love:</strong><br>The mariner's redemption begins only when, watching the luminous water snakes under the moon, he overcomes his disgust, perceives their divine beauty, and blesses them unaware. The curse breaks, the dead bird falls from his neck into the sea, and he learns the eternal moral: <em>'He prayeth best, who loveth best / All things both great and small; / For the dear God who loveth us, / He made and loveth all.'</em></p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Breakdown 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Sacred bond with nature violated by shooting the Albatross</span><span class=\"marking-marks\">2½ Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Dead Albatross hung around neck as physical manifestation of guilt</span><span class=\"marking-marks\">2½ Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Spiritual redemption through loving all living creatures ('He prayeth best...')</span><span class=\"marking-marks\">3 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\"><span>🎯 Competency-Based & Value-Based Questions — Unit 10</span><span class=\"cbq-badge\">CBSE 2026-27</span></div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\" style=\"border-left:4px solid #0284c7;\">\n        <div class=\"cbq-type\" style=\"color:#0284c7;\">Supernatural Atmosphere & Imagery</div>\n        <div class=\"cbq-question\"><strong>Analysis:</strong> How does Coleridge use visual imagery and supernatural similes to evoke the terrifying stillness of the doldrums?</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\n        <div class=\"cbq-answer\"><p>Coleridge creates eerie claustrophobia using vivid similes: the motionless ship is 'as idle as a painted ship upon a painted ocean', turning reality into an artificial frozen canvas. The 'bloody Sun at noon' in a 'copper sky' evokes suffocating heat, while 'slimy things did crawl with legs upon the slimy sea' stimulates visceral disgust, dramatizing the nightmare of spiritual alienation.</p></div>\n      </div>\n    </div>\n  </div>\n  <div class=\"chapter-nav-btns\">\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(9)\">← Previous Unit</button>\n    <button class=\"ch-nav-btn\" onclick=\"window.scrollTo({top:0,behavior:'smooth'})\">↑ Back to Top</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(11)\">Next Unit →</button>\n  </div>\n</section>\n","11":"<section class=\"chapter-section\" id=\"ch11\" data-book=\"Poetry\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">P.5</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">COMMUNICATIVE POETRY</div>\n      <h2>Poem 5: Snake</h2>\n      <p>D.H. Lawrence — Instinctive Wonder, Conditioned Fear & The Guilt of Human Cruelty — CBSE Marking Scheme 2026-27</p>\n    </div>\n  </div>\n  <div class=\"poem-display-box\">\n    <div class=\"poem-body\">A snake came to my water-trough\nOn a hot, hot day, and I in pyjamas for the heat,\nTo drink there.\n\nIn the deep, strange-scented shade of the great dark carob-tree\nI came down the steps with my pitcher\nAnd must wait, must stand and wait, for there he was at the trough before me.\n\nHe reached down from a fissure in the earth-wall in the gloom\nAnd trailed his yellow-brown slackness soft-bellied down, over the edge of the stone trough\nAnd rested his throat upon the stone bottom,\nAnd where the water had dripped from the tap, in a small clearness,\nHe sipped with his straight mouth,\nSoftly drank through his straight gums, into his slack long body,\nSilently.</div>\n    <div class=\"poet-name\">— D.H. Lawrence</div>\n  </div>\n\n  <div class=\"ex-div\">I. Literature Reader Textbook Solutions & Analysis — CBSE Marking Scheme 2026-27</div>\n\n  <div class=\"q-card\" id=\"cp5_1\">\n    <div class=\"q-head\" onclick=\"toggleQ('cp5_1')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">Why did the poet go to the water trough? Describe the atmosphere and his attire.</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>The poet went to his garden water-trough with a pitcher to fetch drinking water. It was a fiercely hot July day in Taormina, Sicily, with Mount Etna smoking in the distance. The heat was so oppressive that the poet was dressed only in his night pyjamas.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Breakdown 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Purpose: Carrying pitcher to collect drinking water at garden trough</span><span class=\"marking-marks\">1½ Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Atmosphere: Scorching Sicilian July day with smoking Etna; wearing pyjamas</span><span class=\"marking-marks\">1½ Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"cp5_2\">\n    <div class=\"q-head\" onclick=\"toggleQ('cp5_2')\">\n      <div class=\"q-num\">Q2</div>\n      <div class=\"q-text\">How did the snake drink water from the trough? How does the poet describe its dignity?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>The golden-brown snake emerged from a fissure in the earth-wall, trailing its soft belly over the stone rim. It rested its throat on the stone bottom, sipping water softly through its straight gums into its long, slack body. It looked around dreamily like a drinking god, flicking its forked tongue and pausing like a peaceful guest.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Breakdown 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Drinking posture: Soft belly on stone, sipping through straight gums</span><span class=\"marking-marks\">1½ Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Dignity: Described as a drinking cattle/guest, majestic and god-like</span><span class=\"marking-marks\">1½ Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"cp5_3\">\n    <div class=\"q-head\" onclick=\"toggleQ('cp5_3')\">\n      <div class=\"q-num\">Q3</div>\n      <div class=\"q-text\">What did the 'voice of education' command the poet to do? What inner conflict ensued?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>The 'voice of human education' whispered that in Sicily, black snakes are harmless while gold snakes are venomous, urging: <em>'He must be killed, take a stick and finish him off.'</em> This sparked a fierce inner struggle: the poet's natural instinct admired the creature as a royal, honored guest, while social training branded his hesitation as cowardice and demanded violence.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Breakdown 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Voice of education: Gold snake is venomous and must be killed with a stick</span><span class=\"marking-marks\">1½ Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Inner conflict: Natural aesthetic reverence vs civilized fear and prejudice</span><span class=\"marking-marks\">1½ Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"cp5_4\">\n    <div class=\"q-head\" onclick=\"toggleQ('cp5_4')\">\n      <div class=\"q-num\">Q4</div>\n      <div class=\"q-text\">Why did the poet throw a clumsy log at the snake? How did he feel immediately afterwards?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>As the snake turned and put its head back into the dark fissure to depart, a sudden wave of petty human revulsion seized the poet. Picking up a clumsy log, he hurled it at the water trough. Though the log missed the snake's body, the snake convulsed with haste and vanished into the wall. Immediately, the poet was overcome with bitter shame, despising himself, his vulgar action, and the pettiness of human education.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Breakdown 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Threw clumsy log out of sudden instinctive horror as snake retreated into hole</span><span class=\"marking-marks\">1½ Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Instant regret: Despised himself and cursed the vulgarity of human training</span><span class=\"marking-marks\">1½ Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"cp5_5\">\n    <div class=\"q-head\" onclick=\"toggleQ('cp5_5')\">\n      <div class=\"q-num\">Q5</div>\n      <div class=\"q-text\">How does D.H. Lawrence's 'Snake' explore the conflict between primal ecological wonder and civilized human prejudice? Why does the poet compare the snake to an 'uncrowned king'?</div>\n      <div class=\"q-marks\">8 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (Max Word Count)</div>\n        <div class=\"answer-text\">\n<p><strong>1. Primal Wonder vs Social Conditioning:</strong><br>Lawrence's poem is an indictment of modern human civilization. Born with an innate capacity to love nature, humans are systematically corrupted by an 'education' of fear, conquest, and violence. The poet instinctively regards the snake as an innocent fellow creature who arrived at the trough first, deserving courtesy as a guest.</p><p><strong>2. The Guilt of Petty Violence:</strong><br>The poet's aggressive act of throwing a log was not self-defense, but an insecure exhibition of false bravado demanded by societal conditioning. The moment the violence was done, he felt tainted by spiritual vulgarity.</p><p><strong>3. The Snake as an 'Uncrowned King':</strong><br>The poet compares the creature to a lord of the underworld—an exiled, magnificent king uncrowned in the dark subterranean depths. Comparing his petty act to the Ancient Mariner's shooting of the Albatross, the poet acknowledges that he missed a sacred chance to commune with a god of the earth, leaving him with an enduring spiritual pettiness to expiate.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Breakdown 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Conflict: Innate ecological reverence vs toxic social education of violence</span><span class=\"marking-marks\">2½ Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Psychological guilt of hurling the log to prove artificial masculinity</span><span class=\"marking-marks\">2½ Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Symbolism of 'uncrowned king' and comparison with Coleridge's Albatross</span><span class=\"marking-marks\">3 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\"><span>🎯 Competency-Based & Value-Based Questions — Unit 11</span><span class=\"cbq-badge\">CBSE 2026-27</span></div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\" style=\"border-left:4px solid #0284c7;\">\n        <div class=\"cbq-type\" style=\"color:#0284c7;\">Philosophical & Psychological Reflection</div>\n        <div class=\"cbq-question\"><strong>Analysis:</strong> Why does the poet refer to his act of throwing the log as a 'petty' crime? What does this word signify?</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\n        <div class=\"cbq-answer\"><p>The word 'petty' signifies smallness of mind, cowardice, and vulgarity. Throwing a log at a peaceful, non-threatening creature whose back was turned did not require bravery; it was an act of cheap, cowardly spite. The poet recognized that human beings often commit unprovoked cruelty simply because their fragile egos cannot tolerate peaceful coexistence with the wild.</p></div>\n      </div>\n    </div>\n  </div>\n  <div class=\"chapter-nav-btns\">\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(10)\">← Previous Unit</button>\n    <button class=\"ch-nav-btn\" onclick=\"window.scrollTo({top:0,behavior:'smooth'})\">↑ Back to Top</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(12)\">Next Unit →</button>\n  </div>\n</section>\n","12":"<section class=\"chapter-section\" id=\"ch12\" data-book=\"Drama\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">D.1</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">COMMUNICATIVE DRAMA</div>\n      <h2>Play 1: The Dear Departed</h2>\n      <p>Stanley Houghton — Social Satire, Filial Greed & Elderly Independence — CBSE Marking Scheme 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">I. Literature Reader Textbook Solutions & Analysis — CBSE Marking Scheme 2026-27</div>\n\n  <div class=\"q-card\" id=\"cd1_1\">\n    <div class=\"q-head\" onclick=\"toggleQ('cd1_1')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">What made Mrs. Amelia Slater assume that her elderly father, Abel Merryweather, was dead?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>Mrs. Amelia Slater went upstairs to take her father a cup of tea. She found him lying motionless, cold as stone, with his eyes closed and no sound of breathing. Instead of calling a doctor to verify death, she jumped to the conclusion that he was dead, immediately ordering her husband to put on black and telegramming her sister Elizabeth to come divide his belongings.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Breakdown 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Found father motionless, cold, and unresponsive in bed</span><span class=\"marking-marks\">1½ Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Failed to call a doctor; immediately assumed death to grab belongings</span><span class=\"marking-marks\">1½ Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"cd1_2\">\n    <div class=\"q-head\" onclick=\"toggleQ('cd1_2')\">\n      <div class=\"q-num\">Q2</div>\n      <div class=\"q-text\">What greedy actions do Amelia and Henry Slater take before the Jordans arrive?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>Fearing that Elizabeth would claim her share of Abel's possessions, Amelia immediately grabs Abel's brand-new pair of leather slippers for Henry. She then bullies Henry into carrying the grandfather's valuable walnut bureau downstairs to their sitting room, replacing it with an old chest of drawers, and claims the grandfather's handsome mantelpiece clock as her own.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Breakdown 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Appropriated grandfather's new slippers for Henry</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Dragged heavy walnut bureau downstairs before Jordans arrived</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Pinched grandfather's valuable clock from his bedroom</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"cd1_3\">\n    <div class=\"q-head\" onclick=\"toggleQ('cd1_3')\">\n      <div class=\"q-num\">Q3</div>\n      <div class=\"q-text\">How do Elizabeth and Ben Jordan behave upon arriving? How is their hypocrisy exposed?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>Elizabeth and Ben Jordan arrive dressed in formal mourning, putting on a show of grief and weeping loudly. However, their concern is entirely monetary: without even going upstairs to look at their father's 'corpse', they immediately demand to search for his will, discuss whether he paid his premium insurance, and squabble over who gets his gold watch and mourning clothes.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Breakdown 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Showed false tears of mourning without checking father's body upstairs</span><span class=\"marking-marks\">1½ Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Quarreled greedily over insurance premium, gold watch, and furniture</span><span class=\"marking-marks\">1½ Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"cd1_4\">\n    <div class=\"q-head\" onclick=\"toggleQ('cd1_4')\">\n      <div class=\"q-num\">Q4</div>\n      <div class=\"q-text\">What shock awaits the daughters when Abel Merryweather walks downstairs alive and hearty?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>Abel Merryweather walks downstairs dressed comfortably, wondering why everyone is dressed in mourning black and staring at him as if he were a ghost. He notices Henry wearing his new slippers and is bewildered to see his prized bureau and clock in the Slaters' sitting room. Young Victoria innocently blurts out that they thought he was dead, revealing the daughters' greed.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Breakdown 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Abel walks down alive, healthy, and perplexed by mourning clothes</span><span class=\"marking-marks\">1½ Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Catches Henry in his slippers and spots his stolen bureau downstairs</span><span class=\"marking-marks\">1½ Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"cd1_5\">\n    <div class=\"q-head\" onclick=\"toggleQ('cd1_5')\">\n      <div class=\"q-num\">Q5</div>\n      <div class=\"q-text\">How is 'The Dear Departed' a biting satire on filial ingratitude, middle-class hypocrisy, and commercialized family relationships? What bombshell does Abel drop at the climax?</div>\n      <div class=\"q-marks\">8 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (Max Word Count)</div>\n        <div class=\"answer-text\">\n<p><strong>1. Satire on Filial Ingratitude:</strong><br>Stanley Houghton satirizes the degrading decay of moral values in suburban middle-class society. The daughters, Amelia Slater and Elizabeth Jordan, view their seventy-two-year-old father not with loving reverence, but as an inconvenient financial encumbrance whose death is celebrated as an opportunity to plunder furniture, jewelry, and insurance money.</p><p><strong>2. Hypocrisy and Pettiness:</strong><br>Both sisters compete in vulgar rivalry, fighting tooth and nail over an old man's clock, bureau, and flannel trousers before his body has even cooled. They care nothing for his welfare, passing him back and forth like a parcel.</p><p><strong>3. Abel's Masterstroke (The Bombshell):</strong><br>Realizing that his daughters are heartless vultures who wished him dead, Abel delivers poetic justice. He announces three life-altering decisions:</p><ul><li>He will alter his will at his lawyer's on Monday, leaving all his money, estate, and possessions entirely to whoever he is living with at the time of his death.</li><li>He will pay his insurance premium himself.</li><li>At twelve o'clock on Monday, he will marry <strong>Mrs. John Shorrocks</strong>, the cheerful landlady of the 'Ring-o'-Bells' pub, who genuinely cares for his comfort.</li></ul><p>Abel walks out triumphant, leaving both greedy sisters stunned, humiliated, and empty-handed.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Breakdown 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Satire on greedy daughters competing for dead father's possessions</span><span class=\"marking-marks\">2½ Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Exposure of hypocrisy: Bureaucracy of grief, mourning clothes, false weeping</span><span class=\"marking-marks\">2½ Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Climactic poetic justice: Rewriting will and marrying Mrs. Shorrocks</span><span class=\"marking-marks\">3 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\"><span>🎯 Competency-Based & Value-Based Questions — Unit 12</span><span class=\"cbq-badge\">CBSE 2026-27</span></div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\" style=\"border-left:4px solid #0284c7;\">\n        <div class=\"cbq-type\" style=\"color:#0284c7;\">Dramatic Irony & Humor</div>\n        <div class=\"cbq-question\"><strong>Analysis:</strong> How does the innocent child Victoria serve as the moral conscience of the family in 'The Dear Departed'?</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\n        <div class=\"cbq-answer\"><p>Ten-year-old Victoria is the only character untouched by greed. When Amelia orders her to help steal the bureau, Victoria asks innocently: 'Are we pinching it?' When Abel descends, Victoria is overjoyed that her grandfather is alive. Her uncorrupted innocence acts as a mirror that magnifies the grotesque greed and moral rot of her parents.</p></div>\n      </div>\n    </div>\n  </div>\n  <div class=\"chapter-nav-btns\">\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(11)\">← Previous Unit</button>\n    <button class=\"ch-nav-btn\" onclick=\"window.scrollTo({top:0,behavior:'smooth'})\">↑ Back to Top</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(13)\">Next Unit →</button>\n  </div>\n</section>\n","13":"<section class=\"chapter-section\" id=\"ch13\" data-book=\"Drama\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">D.2</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">COMMUNICATIVE DRAMA</div>\n      <h2>Play 2: Julius Caesar</h2>\n      <p>William Shakespeare — Political Idealism, Betrayal, Rhetoric & Crowd Psychology — CBSE Marking Scheme 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">I. Literature Reader Textbook Solutions & Analysis — CBSE Marking Scheme 2026-27</div>\n\n  <div class=\"q-card\" id=\"cd2_1\">\n    <div class=\"q-head\" onclick=\"toggleQ('cd2_1')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">What ominous omens and nightmares preceded Caesar's assassination on the Ides of March?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>A tempest tossed the city with supernatural portents: graves yawned and yielded up their dead, a lion roamed the Capitol, men on fire walked unhurt, and a screech-owl hooted in the marketplace at noon. Caesar's wife, Calpurnia, had a terrifying nightmare where Caesar's statue spouted blood from a hundred spouts, and smiling Romans washed their hands in it, begging him not to leave the palace.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Breakdown 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Supernatural omens: Graves open, roaming lion, fiery men, screech-owl at noon</span><span class=\"marking-marks\">1½ Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Calpurnia's nightmare: Caesar's statue spouting blood with Romans bathing hands</span><span class=\"marking-marks\">1½ Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"cd2_2\">\n    <div class=\"q-head\" onclick=\"toggleQ('cd2_2')\">\n      <div class=\"q-num\">Q2</div>\n      <div class=\"q-text\">How did Decius Brutus persuade Caesar to ignore Calpurnia's fears and go to the Senate House?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>Decius Brutus skillfully manipulated Caesar's vanity through clever flattery:</p><ul><li>He reinterpreted Calpurnia's nightmare favorably, claiming the spouting blood signified that Rome would draw new life and reviving influence from Caesar's sovereign reign.</li><li>He whispered that the Senate had resolved to offer Caesar the crown that day, and if he stayed home fearing a woman's dreams, senators would mock him as a coward.</li></ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Breakdown 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Reinterpreted dream: Statues spouting blood means Rome draws reviving life</span><span class=\"marking-marks\">1½ Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Appealed to pride: Senate offering crown; warned they would mock him as coward</span><span class=\"marking-marks\">1½ Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"cd2_3\">\n    <div class=\"q-head\" onclick=\"toggleQ('cd2_3')\">\n      <div class=\"q-num\">Q3</div>\n      <div class=\"q-text\">How did the conspirators stage Caesar's assassination under the pretext of Metellus Cimber's petition?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>Metellus Cimber knelt before Caesar, begging the repeal of his banished brother Publius. When Caesar arrogantly refused, declaring himself as constant and unmoving as the Northern Star, the conspirators crowded around him on their knees. Casca struck first from behind, shouting: <em>'Speak, hands, for me!'</em> All conspirators stabbed him, and seeing his beloved friend Brutus deliver the final blow, Caesar uttered his tragic last words: <em>'Et tu, Brute?—Then fall, Caesar!'</em> and died.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Breakdown 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Pretext: Metellus Cimber's petition to repeal his brother's banishment</span><span class=\"marking-marks\">1½ Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Assassination: Casca stabs first; Brutus stabs last; famous cry 'Et tu, Brute?'</span><span class=\"marking-marks\">1½ Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"cd2_4\">\n    <div class=\"q-head\" onclick=\"toggleQ('cd2_4')\">\n      <div class=\"q-num\">Q4</div>\n      <div class=\"q-text\">What strategic blunder did Brutus commit regarding Mark Antony after the assassination?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>Overruling Cassius's realistic warnings, Brutus committed two fatal blunders: (i) he spared Mark Antony's life, and (ii) he permitted Antony to deliver a funeral oration over Caesar's body in the marketplace, imposing the naive condition that Antony must speak only after Brutus and praise Caesar without condemning the conspirators. Brutus underestimated Antony's oratorical genius and deep loyalty.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Breakdown 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Spared Antony's life despite Cassius's warnings of danger</span><span class=\"marking-marks\">1½ Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Permitted Antony to speak at Caesar's funeral, assuming mob would remain calm</span><span class=\"marking-marks\">1½ Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"cd2_5\">\n    <div class=\"q-head\" onclick=\"toggleQ('cd2_5')\">\n      <div class=\"q-num\">Q5</div>\n      <div class=\"q-text\">Compare the funeral orations of Brutus and Mark Antony. How does Antony masterfully sway the Roman plebeians from praising Brutus to demanding the conspirators' heads?</div>\n      <div class=\"q-marks\">8 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (Max Word Count)</div>\n        <div class=\"answer-text\">\n<p><strong>1. Brutus's Speech (Intellectual Logic & Patriotism):</strong><br>Brutus speaks in prose, appealing strictly to abstract reason, republican virtue, and civic duty. His central thesis is: <em>'Not that I loved Caesar less, but that I loved Rome more.'</em> He justifies assassination by branding Caesar ambitious, demanding whether Romans would rather live as slaves under Caesar or free men in a republic. The mob, persuaded by his cold rhetoric, shouts in praise: <em>'Let him be Caesar!'</em></p><p><strong>2. Mark Antony's Speech (Emotional Masterpiece & Irony):</strong><br>Antony speaks in passionate blank verse, systematically dismantling Brutus's claim of Caesar's ambition using concrete evidence:</p><ul><li>Caesar brought countless captives whose ransoms filled Roman public coffers.</li><li>When the poor cried, Caesar wept; ambition should be made of sterner stuff.</li><li>On the Lupercal, Caesar thrice refused the kingly crown.</li></ul><p><strong>3. Rhetorical Irony and Climax:</strong><br>Antony repeats the biting refrain: <em>'Yet Brutus says he was ambitious; and Brutus is an honourable man.'</em> He displays Caesar's blood-soaked mantle, pointing out each conspirator's dagger slash, highlighting Brutus's cut as <em>'the most unkindest cut of all'</em>. Finally, he reads Caesar's will, which bequeathed seventy-five drachmas and private orchards to every Roman citizen. The mob erupts in mutinous fury, shouting: <em>'Revenge! About! Seek! Burn! Fire! Kill! Slay!'</em>, completely overthrowing the conspirators through the sheer power of rhetoric.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Breakdown 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Brutus's speech: Abstract prose, logic, patriotism ('loved Rome more')</span><span class=\"marking-marks\">2½ Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Antony's counter-arguments proving Caesar was not ambitious (ransom, tears, crown)</span><span class=\"marking-marks\">2½ Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Antony's theatrical props: Mantle, dagger wounds, Caesar's will, incitement to mutiny</span><span class=\"marking-marks\">3 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\"><span>🎯 Competency-Based & Value-Based Questions — Unit 13</span><span class=\"cbq-badge\">CBSE 2026-27</span></div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\" style=\"border-left:4px solid #0284c7;\">\n        <div class=\"cbq-type\" style=\"color:#0284c7;\">Rhetoric & Crowd Psychology</div>\n        <div class=\"cbq-question\"><strong>Analysis:</strong> How does Shakespeare depict the fickleness and emotional volatility of the Roman mob in Julius Caesar?</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\n        <div class=\"cbq-answer\"><p>Shakespeare presents the Roman mob as an unstable, easily swayed beast driven by emotion rather than political conviction. Within fifteen minutes, the plebeians switch from hailing Brutus as a hero and wanting to crown him, to screaming for his blood and burning the conspirators' homes after Antony shows them Caesar's wounds and reads his will. The scene is a timeless warning on how populist rhetoric can weaponize crowd hysteria against democratic order.</p></div>\n      </div>\n    </div>\n  </div>\n  <div class=\"chapter-nav-btns\">\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(12)\">← Previous Unit</button>\n    <button class=\"ch-nav-btn\" onclick=\"window.scrollTo({top:0,behavior:'smooth'})\">↑ Back to Top</button>\n    <div></div>\n  </div>\n</section>\n"};
